const { writeFileSync } = require('node:fs');
const { createRequire } = require('node:module');
const { resolve } = require('node:path');
const ts = createRequire(resolve(__dirname, '../../typescript/package.json'))('typescript');

const header =
  '/** Generated by gen/sdk-public-exports.cjs; edit the producer, then regenerate. */\n';

/** Resolve aliases before classifying exported values and types, preserving classes/enums that occupy both namespaces. */
function exportKind(checker, symbol) {
  const target =
    symbol.flags & ts.SymbolFlags.Alias
      ? checker.getAliasedSymbol(symbol)
      : symbol;
  return {
    name: symbol.name,
    value: Boolean(target.flags & ts.SymbolFlags.Value),
    type: Boolean(target.flags & ts.SymbolFlags.Type),
  };
}

/** Read the compiler's complete public surface; unresolved modules fail before any generated output is replaced. */
function publicSurface(program, file) {
  const source = program.getSourceFile(file);
  const checker = program.getTypeChecker();
  const symbol = source && checker.getSymbolAtLocation(source);
  if (!symbol) throw new Error(`SDK export module cannot be resolved: ${file}`);
  return checker
    .getExportsOfModule(symbol)
    .map(
      /** Preserve both runtime and type identity for the before/after contract comparison. */
      (entry) => exportKind(checker, entry),
    )
    .sort(
      /** Use deterministic ASCII order independently of filesystem enumeration. */
      (left, right) => left.name.localeCompare(right.name, 'en'),
    );
}

/** Collect explicitly exported names so star expansion preserves TypeScript's explicit-export precedence. */
function explicitNames(source) {
  const names = new Set();
  for (const statement of source.statements) {
    if (!ts.isExportDeclaration(statement) || !statement.exportClause) continue;
    if (ts.isNamedExports(statement.exportClause)) {
      for (const element of statement.exportClause.elements)
        names.add(element.name.text);
    }
  }
  return names;
}

/** Expand one wildcard into named type/value specifiers using the actual resolved target module. */
function namedDeclaration(checker, declaration, reserved) {
  const symbol = checker.getSymbolAtLocation(declaration.moduleSpecifier);
  if (!symbol)
    throw new Error(
      `Unresolved SDK export: ${declaration.moduleSpecifier.getText()}`,
    );
  const members = checker
    .getExportsOfModule(symbol)
    .map(
      /** Classify each public target member before constructing explicit export syntax. */
      (member) => exportKind(checker, member),
    )
    .filter(
      /** Wildcards never forward default exports or override explicit declarations. */
      (member) => member.name !== 'default' && !reserved.has(member.name),
    )
    .sort(
      /** Keep repeat generation byte-identical regardless of compiler traversal order. */
      (left, right) => left.name.localeCompare(right.name, 'en'),
    );
  return ts.factory.createExportDeclaration(
    undefined,
    declaration.isTypeOnly,
    ts.factory.createNamedExports(
      members.map(
        /** Interfaces and aliases must remain type-only under isolatedModules and verbatim module syntax. */
        (member) =>
          ts.factory.createExportSpecifier(
            !declaration.isTypeOnly && !member.value,
            undefined,
            member.name,
          ),
      ),
    ),
    declaration.moduleSpecifier,
  );
}

/** Construct deterministic explicit barrels in memory while retaining authored declarations outside export stars. */
function renderedBarrel(program, file) {
  const source = program.getSourceFile(file);
  if (!source) throw new Error(`Missing SDK barrel: ${file}`);
  const checker = program.getTypeChecker();
  const reserved = explicitNames(source);
  const statements = source.statements.map(
    /** Only replace star declarations; all other syntax is printed from its original AST. */
    (statement) =>
      ts.isExportDeclaration(statement) &&
      !statement.exportClause &&
      statement.moduleSpecifier
        ? namedDeclaration(checker, statement, reserved)
        : statement,
  );
  const printer = ts.createPrinter({
    newLine: ts.NewLineKind.LineFeed,
    removeComments: true,
  });
  return (
    header + printer.printFile(ts.factory.updateSourceFile(source, statements))
  );
}

/** Replace producer-owned barrels and assert exact exported type/value identity after rewriting them. */
function makeExportsExplicit(files) {
  const options = {
    target: ts.ScriptTarget.ES2022,
    moduleResolution: ts.ModuleResolutionKind.Node10,
    skipLibCheck: true,
  };
  const before = ts.createProgram(files, options);
  const surfaces = files.map(
    /** Snapshot the compiler-resolved contract before any output file is changed. */
    (file) => publicSurface(before, file),
  );
  const rendered = files.map(
    /** Resolve all original wildcard targets before replacing any shared barrel. */
    (file) => renderedBarrel(before, file),
  );
  files.forEach(
    /** Write only the explicit producer-owned files selected by the caller. */
    (file, index) => writeFileSync(file, rendered[index]),
  );
  const after = ts.createProgram(files, options);
  files.forEach(
    /** A missing or reclassified export is a producer failure, never an accepted API change. */
    (file, index) => {
      if (
        JSON.stringify(surfaces[index]) !==
        JSON.stringify(publicSurface(after, file))
      )
        throw new Error(`SDK public export contract changed: ${file}`);
    },
  );
}

module.exports = { makeExportsExplicit };
